import PptxGenJS from "pptxgenjs";
const COLORS = {
    primary: "2563EB",
    secondary: "0F172A",
    text: "334155",
    light: "F8FAFC",
    border: "E2E8F0",
    white: "FFFFFF",
    muted: "64748B",
};
const generateppt = async (data) => {
    try {
        const ppt = new PptxGenJS(); // fresh instance every call
        ppt.layout = "LAYOUT_WIDE";
        ppt.title = data.title;
        ppt.author = "Gothalo AI";
        ppt.subject = data.title;
        ppt.company = "Gothalo AI";
        ppt.theme = {
            headFontFace: "Aptos",
            bodyFontFace: "Aptos",
        };
        addcover(ppt, data);
        data.slides.forEach((s, i) => {
            addslide(ppt, s.title, s.points, i + 1, data.slides.length);
        });
        addthankyou(ppt);
        // Generate actual file bytes as a Buffer for upload
        const buffer = (await ppt.write({
            outputType: "nodebuffer",
        }));
        return buffer;
    }
    catch (error) {
        console.error("generateppt failed:", error);
        throw error; // don't swallow — let the caller know it failed
    }
};
const addcover = (ppt, data) => {
    const slide = ppt.addSlide();
    slide.background = { color: COLORS.primary };
    slide.addShape(ppt.ShapeType.rect, {
        x: 0,
        y: 0,
        w: 13.13,
        h: 0.18,
        fill: { color: "60A5FA" },
        line: { color: "60A5FA" },
    });
    slide.addText(data.title, {
        x: 0.7,
        y: 1.7,
        w: 12,
        h: 0.8,
        align: "center",
        color: COLORS.white,
        bold: true,
        fontSize: 28,
    });
    slide.addText(data.subtitle, {
        x: 1,
        y: 2.8,
        w: 11.5,
        h: 0.4,
        align: "center",
        color: "DBEAFE",
        fontSize: 15,
    });
    slide.addText("Generated by Gothalo AI", {
        x: 1,
        y: 3.3,
        w: 11.5,
        h: 0.4,
        align: "center",
        color: "DBEAFE",
        fontSize: 15,
    });
};
const addslide = (ppt, title, points, page, total) => {
    const slide = ppt.addSlide();
    slide.background = { color: COLORS.white };
    slide.addText(title, {
        x: 0.6,
        y: 0.35,
        w: 10,
        h: 0.4,
        color: COLORS.primary,
        bold: true,
        fontSize: 24,
    });
    slide.addShape(ppt.ShapeType.line, {
        x: 0.6,
        y: 0.85,
        w: 12,
        h: 0,
        line: { color: COLORS.border, width: 1.2 },
    });
    const vpoints = points.slice(0, 6);
    vpoints.forEach((p, i) => {
        const y = 1.2 + i * 0.75;
        slide.addShape(ppt.ShapeType.roundRect, {
            x: 0.7,
            y: y,
            w: 12,
            h: 0.58,
            fill: { color: i % 2 ? "F8FAFC" : "EFF6FF" },
            line: { color: COLORS.border },
            rectRadius: 0.08,
        });
        slide.addShape(ppt.ShapeType.ellipse, {
            x: 0.92,
            y: y + 0.18,
            w: 0.12,
            h: 0.12,
            fill: { color: COLORS.primary },
            line: { color: COLORS.primary },
        });
        slide.addText(p, {
            x: 1.2,
            y: 0.08 + y,
            w: 11,
            h: 0.35,
            fit: "shrink",
            color: COLORS.text,
            fontSize: 15,
        });
    });
    // Footer — drawn once per slide, after all bullets
    slide.addText(`${page}/${total}`, {
        x: 12.1,
        y: 6.9,
        w: 0.8,
        h: 0.2,
        align: "right",
        fontSize: 10,
        color: COLORS.muted,
    });
    slide.addText("Gothalo AI", {
        x: 0.6,
        y: 6.9,
        w: 2,
        h: 0.2,
        fontSize: 10,
        color: COLORS.muted,
    });
};
const addthankyou = (ppt) => {
    const slide = ppt.addSlide();
    slide.background = { color: COLORS.secondary };
    slide.addText("Thank You", {
        x: 0,
        y: 2.2,
        w: 13.33,
        h: 0.8,
        align: "center",
        color: COLORS.white,
        fontSize: 34,
        bold: true,
    });
    slide.addText("Generated By Gothalo AI", {
        x: 0,
        y: 6.9,
        w: 13.33,
        h: 0.2,
        align: "center",
        color: "94A3B8",
        fontSize: 18,
    });
};
export { generateppt };
